const ITM_ORIGIN = "https://itm-void-excepcional.pages.dev";
const DEFAULT_STORE_LIVE_PUBLIC_URL = "https://itm-store-live.ontiverosfrancisco059.workers.dev";

const TEMPLATE = {
  "dist/app.js": "",
  "dist/assets/hero-neutral.svg": "",
  "dist/assets/logo-neutral.svg": "",
  "dist/assets/producto-generico.svg": "",
  "dist/carrito.html": "",
  "dist/detalle.html": "",
  "dist/home.css": "",
  "dist/index.html": "",
  "dist/mis-pedidos.html": "",
  "dist/perfil-de-usuario.html": "",
  "dist/store-design-overrides.css": "LyogT3ZlcnJpZGVzIGRlIGRpc2VubyBwdWJsaWNhZG9zIGRlc2RlIEV4Y2VwY2lvbmFsIEJ1aWxkLiAqLwo=",
  "dist/store-design.css": "",
  "dist/store-design.js": "",
  "dist/store-preview.js": "",
  "dist/styles.css": "",
  "dist/tienda.html": ""
};

const html = value => String(value ?? "").replace(/[&<>'"]/g, character => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  "'": "&#39;",
  '"': "&quot;"
}[character]));

function js(value) {
  let out = "";
  for (const character of String(value ?? "")) {
    if (character === "\\") out += "\\\\";
    else if (character === '"') out += '\\"';
    else if (character === "\u0060") out += "\\\u0060";
    else if (character === "$") out += "\\$";
    else if (character === "\n") out += "\\n";
    else if (character === "\r") out += "\\r";
    else if (character === "\u2028") out += "\\u2028";
    else if (character === "\u2029") out += "\\u2029";
    else out += character;
  }
  return out;
}

function decode(value) {
  const binary = atob(value);
  const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function encode(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (let index = 0; index < bytes.length; index += 8192) {
    binary += String.fromCharCode(...bytes.subarray(index, index + 8192));
  }
  return btoa(binary);
}

function render(text, file, projectName, itmProjectId) {
  const name = file.endsWith(".js") ? js(projectName) : html(projectName);
  const upper = file.endsWith(".js")
    ? js(projectName.toUpperCase())
    : html(projectName.toUpperCase());
  return text
    .split("__EB_PROJECT_NAME_UPPER__").join(upper)
    .split("__EB_PROJECT_NAME__").join(name)
    .split("__EB_ITM_PROJECT_ID__").join(itmProjectId);
}

function storeLiveUrl(value) {
  const candidate = String(value || DEFAULT_STORE_LIVE_PUBLIC_URL).trim().replace(/\/+$/, "");
  try {
    const url = new URL(candidate);
    return url.protocol === "https:" ? url.toString().replace(/\/+$/, "") : DEFAULT_STORE_LIVE_PUBLIC_URL;
  } catch {
    return DEFAULT_STORE_LIVE_PUBLIC_URL;
  }
}

export function buildGeneratedSiteFiles({ projectId, itmProjectId, projectName, storeLiveUrl: configuredStoreLiveUrl }) {
  const name = String(projectName || "Mi negocio").trim().slice(0, 160) || "Mi negocio";
  const config = JSON.stringify({
    project_id: String(itmProjectId),
    exceptional_project_id: String(projectId),
    api_origin: ITM_ORIGIN,
    store_live_url: storeLiveUrl(configuredStoreLiveUrl),
    site_name: name,
    whatsapp_number: "",
    version: 4
  }, null, 2) + "\n";

  const files = Object.entries(TEMPLATE).map(([file, data]) => ({
    path: file,
    data: encode(render(decode(data), file, name, String(itmProjectId)))
  }));

  files.push({ path: "dist/store-config.json", data: encode(config) });
  files.push({
    path: "README.md",
    data: encode("# " + name + "\n\nSitio creado desde Excepcional Build. No edites dist/store-config.json: conecta la tienda aislada de este proyecto.\n")
  });

  return files;
}
